def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for p in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    py, px = p
                    if 0 <= py < h and 0 <= px < w and p not in seen and grid[py][px] == color:
                        seen.add(p)
                        stack.append(p)
            miny = min(y for y, x in cells)
            minx = min(x for y, x in cells)
            shape = frozenset((y-miny, x-minx) for y, x in cells)
            components.append((color, cells, shape))
    eight_shapes = {shape for color, _, shape in components if color == 8}
    out = [row[:] for row in grid]
    for color, cells, shape in components:
        if color != 8 and shape in eight_shapes:
            for y, x in cells:
                out[y][x] = 8
    return out
